const $=s=>document.querySelector(s);let view='properties',items=[];const labels={properties:'Properties',posts:'Blog posts',enquiries:'Enquiries'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,options={}){const r=await fetch(url,{headers:{'content-type':'application/json',...(options.headers||{})},...options});const data=await r.json();if(!r.ok)throw new Error(data.error||'Request failed');return data}
function notify(text){const n=$('#notice');n.textContent=text;n.style.display='block';setTimeout(()=>n.style.display='none',3000)}
async function load(){try{items=await api(`/api/admin/${view}`);render()}catch(e){$('#content').innerHTML=`<div class="empty">${esc(e.message)}<br><small>Make sure Cloudflare Access and the database binding are configured.</small></div>`}}
function render(){if(!items.length){$('#content').innerHTML=`<div class="empty">No ${labels[view].toLowerCase()} yet.</div>`;return}$('#content').innerHTML=items.map(x=>`<article class="item"><div><span class="badge">${esc(x.status)}</span><h3>${esc(x.title||x.name)}</h3><div class="meta">${esc(x.location||x.category||x.phone)} · ${esc(x.created_at)}</div></div><div class="item-actions">${view==='enquiries'?`<button data-done="${x.id}">Mark handled</button>`:`<button data-edit="${x.id}">Edit</button><button data-delete="${x.id}">Delete</button>`}</div></article>`).join('')}
function fields(x={}){const image=`<div class="field"><label>Image URL</label><input name="image_url" value="${esc(x.image_url)}"></div><div class="field"><label>Or upload an image</label><input type="file" name="image_file" accept="image/*"></div>`;if(view==='properties')return `<div class="field"><label>Title</label><input name="title" required value="${esc(x.title)}"></div><div class="row"><div class="field"><label>Purpose</label><select name="purpose"><option value="sale">For sale</option><option value="rent">For rent</option><option value="investment">Investment</option></select></div><div class="field"><label>Type</label><input name="property_type" value="${esc(x.property_type||'House')}"></div></div><div class="row"><div class="field"><label>Location</label><input name="location" required value="${esc(x.location)}"></div><div class="field"><label>Price</label><input name="price" value="${esc(x.price)}"></div></div><div class="field"><label>Description</label><textarea name="description" required rows="4">${esc(x.description)}</textarea></div>${image}<div class="row"><div class="field"><label>Status</label><select name="status"><option value="draft">Draft</option><option value="published">Published</option><option value="sold">Sold</option><option value="rented">Rented</option></select></div><div class="field"><label><input type="checkbox" name="featured" ${x.featured?'checked':''}> Featured</label></div></div>`;return `<div class="field"><label>Title</label><input name="title" required value="${esc(x.title)}"></div><div class="field"><label>Category</label><input name="category" value="${esc(x.category)}"></div><div class="field"><label>Excerpt</label><textarea name="excerpt" required>${esc(x.excerpt)}</textarea></div><div class="field"><label>Article</label><textarea name="content" required rows="7">${esc(x.content)}</textarea></div>${image}<div class="field"><label>Status</label><select name="status"><option value="draft">Draft</option><option value="published">Published</option></select></div>`}
function openEditor(x={}){$('#editor-title').textContent=`${x.id?'Edit':'Add'} ${view==='properties'?'property':'post'}`;$('#fields').innerHTML=fields(x);$('#editor-form').elements.id.value=x.id||'';for(const k of ['purpose','status'])if(x[k]&&$('#editor-form').elements[k])$('#editor-form').elements[k].value=x[k];$('#editor').showModal()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelector('nav .active').classList.remove('active');b.classList.add('active');view=b.dataset.view;$('#title').textContent=labels[view];$('#new').style.display=view==='enquiries'?'none':'';$('#new').textContent=`+ Add ${view==='properties'?'property':'post'}`;load()});
$('#new').onclick=()=>openEditor();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>$('#editor').close());
$('#content').onclick=async e=>{const edit=e.target.dataset.edit,del=e.target.dataset.delete,done=e.target.dataset.done;if(edit)openEditor(items.find(x=>x.id==edit));if(del&&confirm('Delete this item?')){await api(`/api/${view}/${del}`,{method:'DELETE'});notify('Deleted');load()}if(done){await api(`/api/enquiries/${done}`,{method:'PATCH',body:JSON.stringify({status:'handled'})});notify('Enquiry updated');load()}};
$('#editor-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),file=f.get('image_file'),v=Object.fromEntries(f);delete v.image_file;v.featured=f.has('featured');const id=v.id;delete v.id;if(file&&file.size){const upload=new FormData();upload.append('file',file);const r=await fetch('/api/admin/upload',{method:'POST',body:upload});const data=await r.json();if(!r.ok)throw new Error(data.error||'Upload failed');v.image_url=data.url}await api(`/api/admin/${view}${id?'/'+id:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(v)});$('#editor').close();notify('Saved successfully');load()};load();
